def compute(vars):
    old = vars["v1"]
    new = vars["v2"]
    if old == 0:
        return None

    change = new - old
    ratio = change / old
    value = ratio * 100

    return {
        "value": value,
        "trace": {
            "old": old,
            "new": new,
            "change": change,
            "change_ratio": ratio,
            "output_meta": {
                "currency": None,
                "scale": "percentage",
                "unit": "percentage"
            }
        }
    }
